import { useEffect, useState } from 'react'
import { useGameStore } from '@/store/gameStore'
import { ArrowLeft, Music, Sparkles } from 'lucide-react'

export default function ContextReadPage() {
  const selectedPoem = useGameStore((s) => s.selectedPoem)
  const selectedPoet = useGameStore((s) => s.selectedPoet)
  const initChat = useGameStore((s) => s.initChat)
  const setView = useGameStore((s) => s.setView)
  const [visibleText, setVisibleText] = useState('')
  const [isComplete, setIsComplete] = useState(false)

  if (!selectedPoem || !selectedPoet) {
    setView('poetSelect')
    return null
  }

  useEffect(() => {
    setVisibleText('')
    setIsComplete(false)
    const text = selectedPoem.backgroundText
    let index = 0

    const timer = setInterval(() => {
      if (index < text.length) {
        setVisibleText(text.slice(0, index + 1))
        index++
      } else {
        setIsComplete(true)
        clearInterval(timer)
      }
    }, 45)

    return () => clearInterval(timer)
  }, [selectedPoem])

  return (
    <div className="h-screen w-screen flex flex-col items-center ink-wash-bg paper-texture overflow-y-auto">
      <div className="w-full max-w-[640px] px-6 py-8 flex flex-col min-h-full">
        <div className="flex items-center gap-4 mb-6">
          <button
            onClick={() => setView('poemSelect')}
            className="w-8 h-8 flex items-center justify-center rounded-sm border border-mo/20 text-mo hover:bg-mo hover:text-xuan-100 transition-all"
          >
            <ArrowLeft size={16} />
          </button>
          <div>
            <h1 className="font-brush text-2xl text-mo tracking-wider">
              {selectedPoem.title}
            </h1>
            <p className="text-xs text-mo-lighter font-serif">
              {selectedPoet.name} · {selectedPoem.dynasty}
            </p>
          </div>
        </div>

        <div className="flex-1 flex flex-col items-center justify-center">
          <div
            className="w-full aspect-video rounded-sm bg-cover bg-center mb-6 relative overflow-hidden"
            style={{ backgroundImage: `url(${selectedPoem.bgImageUrl})` }}
          >
            <div className="absolute inset-0 bg-black/20" />
            <div className="absolute top-3 right-3 flex items-center gap-1.5 bg-black/30 backdrop-blur-sm px-2 py-1 rounded-sm">
              <Music size={10} className="text-yuehuang" />
              <span className="text-[10px] text-white/80 font-serif">播放背景乐</span>
            </div>
          </div>

          <div className="w-full bg-xuan-100/70 border border-mo/10 rounded-sm p-6 relative">
            <div className="absolute top-3 left-4 text-mo/10 font-brush text-4xl select-none">
              卷
            </div>

            <p className="font-serif text-sm text-mo leading-[2.2] min-h-[120px] relative z-10">
              {visibleText}
              {!isComplete && (
                <span className="inline-block w-0.5 h-4 bg-mo/40 ml-0.5 animate-pulse align-middle" />
              )}
            </p>

            {isComplete && (
              <div className="mt-6 flex justify-center animate-fade-in">
                <button
                  onClick={initChat}
                  className="group flex items-center gap-2 px-8 py-3 border border-mo/30 rounded-sm font-serif text-sm text-mo hover:bg-mo hover:text-xuan-100 transition-all duration-500"
                >
                  <Sparkles size={14} className="text-yuehuang group-hover:text-yuehuang" />
                  入梦
                  <Sparkles size={14} className="text-yuehuang group-hover:text-yuehuang" />
                </button>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  )
}
