import { useGameStore } from '@/store/gameStore'

export default function SceneArea() {
  const selectedPoem = useGameStore((s) => s.selectedPoem)

  if (!selectedPoem) return null

  return (
    <div className="relative h-full w-full overflow-hidden">
      <div
        className="absolute inset-0 bg-cover bg-center"
        style={{ backgroundImage: `url(${selectedPoem.bgImageUrl})` }}
      />
      <div className="absolute inset-0 bg-black/30" />

      <div className="absolute bottom-4 left-0 right-0 flex flex-col items-center z-10">
        <h2 className="font-brush text-xl text-white/90 tracking-wider">
          {selectedPoem.title}
        </h2>
        <p className="text-xs text-white/50 font-serif tracking-widest mt-0.5">
          {selectedPoem.dynasty}
        </p>
      </div>
    </div>
  )
}
