import { create } from 'zustand'
import type { ChatMessage, LLMMessage, GameView, Poet, PoemScenario } from '@/types'
import { poets } from '@/config/gameData'
import { callLLM, resetMockIndex } from '@/services/llmService'

interface GameStore {
  currentView: GameView
  selectedPoet: Poet | null
  selectedPoem: PoemScenario | null
  messages: ChatMessage[]
  isResolved: boolean
  isTransitioning: boolean
  isLoading: boolean
  ttsEnabled: boolean
  isPlaying: boolean
  playingMessageId: string | null

  setView: (view: GameView) => void
  selectPoet: (poet: Poet) => void
  selectPoem: (poem: PoemScenario) => void
  sendMessage: (content: string) => Promise<void>
  returnToPoemSelect: () => void
  resetGame: () => void
  initChat: () => void
  showHint: () => void
  toggleTTS: () => void
  speak: (text: string, messageId: string) => void
  stopSpeaking: () => void
}

function generateId(): string {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 7)
}

const greetings: Record<string, { text: string; emotion: ChatMessage['emotion'] }> = {
  'libai-0': {
    text: '花间一壶酒，独酌无相亲……这位小友，可愿与李某共饮此杯？',
    emotion: 'calm',
  },
  'libai-1': {
    text: '床前明月光，疑是地上霜……旅人啊，你也在这异乡之夜难以入眠吗？',
    emotion: 'sad',
  },
  'dufu-0': {
    text: '八月秋高风怒号，卷我屋上三重茅……唉，这位后生，老夫这茅屋……怕是撑不过今秋了。',
    emotion: 'sad',
  },
  'sushi-0': {
    text: '十年生死两茫茫……知己啊，我方才梦见她了，她还是那么美……',
    emotion: 'sad',
  },
  'sushi-1': {
    text: '莫听穿林打叶声，何妨吟啸且徐行。小友，这雨中的景致，别有一番风味啊。',
    emotion: 'calm',
  },
}

export const useGameStore = create<GameStore>((set, get) => ({
  currentView: 'title',
  selectedPoet: null,
  selectedPoem: null,
  messages: [],
  isResolved: false,
  isTransitioning: false,
  isLoading: false,
  ttsEnabled: true,
  isPlaying: false,
  playingMessageId: null,

  setView: (view: GameView) => set({ currentView: view }),

  selectPoet: (poet: Poet) => {
    set({ selectedPoet: poet, currentView: 'poemSelect' })
  },

  selectPoem: (poem: PoemScenario) => {
    set({ selectedPoem: poem, currentView: 'contextRead' })
  },

  initChat: () => {
    const poem = get().selectedPoem
    if (!poem) return

    const greetingConfig = greetings[poem.id]
    const greeting: ChatMessage = {
      id: generateId(),
      role: 'npc',
      content: greetingConfig?.text ?? '小友，欢迎来到这诗境之中。',
      emotion: greetingConfig?.emotion ?? 'calm',
      timestamp: Date.now(),
    }

    set({
      messages: [greeting],
      isResolved: false,
      isTransitioning: false,
      currentView: 'chat',
    })

    if (get().ttsEnabled) {
      get().speak(greeting.content, greeting.id)
    }
  },

  sendMessage: async (content: string) => {
    const state = get()
    if (state.isLoading || state.isResolved || state.isTransitioning) return

    const playerMessage: ChatMessage = {
      id: generateId(),
      role: 'player',
      content,
      timestamp: Date.now(),
    }

    set({
      messages: [...state.messages, playerMessage],
      isLoading: true,
    })

    try {
      const poem = state.selectedPoem
      if (!poem) throw new Error('No poem selected')

      const llmMessages: LLMMessage[] = [...state.messages, playerMessage]
        .filter((m) => m.role === 'player' || m.role === 'npc')
        .map((m) => ({
          role: m.role === 'player' ? 'user' : 'assistant',
          content: m.content,
        }))

      const response = await callLLM(llmMessages, poem.systemPrompt, poem.id)

      const npcMessage: ChatMessage = {
        id: generateId(),
        role: 'npc',
        content: response.reply,
        emotion: response.emotion,
        timestamp: Date.now(),
      }

      set((s) => ({
        messages: [...s.messages, npcMessage],
        isLoading: false,
        isResolved: response.is_resolved,
      }))

      if (get().ttsEnabled) {
        get().speak(response.reply, npcMessage.id)
      }

      if (response.is_resolved) {
        setTimeout(() => {
          set({ isTransitioning: true })
        }, 2000)
      }
    } catch {
      const errorMessage: ChatMessage = {
        id: generateId(),
        role: 'npc',
        content: '……（一阵风吹过，话语消散在风中）',
        emotion: 'calm',
        timestamp: Date.now(),
      }

      set((s) => ({
        messages: [...s.messages, errorMessage],
        isLoading: false,
      }))
    }
  },

  showHint: () => {
    const poem = get().selectedPoem
    if (!poem) return

    const hintMessage: ChatMessage = {
      id: generateId(),
      role: 'system',
      content: `【锦囊】${poem.hintText}`,
      timestamp: Date.now(),
    }

    set((s) => ({
      messages: [...s.messages, hintMessage],
    }))
  },

  returnToPoemSelect: () => {
    get().stopSpeaking()
    set({
      currentView: 'poemSelect',
      isTransitioning: false,
      isResolved: false,
      messages: [],
      selectedPoem: null,
    })
  },

  resetGame: () => {
    resetMockIndex()
    get().stopSpeaking()
    set({
      currentView: 'title',
      selectedPoet: null,
      selectedPoem: null,
      messages: [],
      isResolved: false,
      isTransitioning: false,
      isLoading: false,
    })
  },

  toggleTTS: () => {
    const state = get()
    const newEnabled = !state.ttsEnabled
    if (!newEnabled && state.isPlaying) {
      state.stopSpeaking()
    }
    set({ ttsEnabled: newEnabled })
  },

  speak: (text: string, messageId: string) => {
    if (typeof window === 'undefined' || !window.speechSynthesis) return

    get().stopSpeaking()

    const selectedPoet = get().selectedPoet
    const utterance = new SpeechSynthesisUtterance(text)
    utterance.lang = 'zh-CN'
    utterance.pitch = selectedPoet?.voiceConfig.pitch ?? 1
    utterance.rate = selectedPoet?.voiceConfig.rate ?? 0.9

    utterance.onstart = () => {
      set({ isPlaying: true, playingMessageId: messageId })
    }

    utterance.onend = () => {
      set({ isPlaying: false, playingMessageId: null })
    }

    utterance.onerror = () => {
      set({ isPlaying: false, playingMessageId: null })
    }

    window.speechSynthesis.speak(utterance)
  },

  stopSpeaking: () => {
    if (typeof window !== 'undefined' && window.speechSynthesis) {
      window.speechSynthesis.cancel()
    }
    set({ isPlaying: false, playingMessageId: null })
  },
}))
