let mockIndex: Record<string, number> = {}

export function resetMockIndex() {
  mockIndex = {}
}

export async function callLLM(
  messages: LLMMessage[],
  systemPrompt: string,
  scenarioId: string
): Promise<LLMResponse> {
  if (!API_URL || !API_KEY) {
    return mockCall(messages, systemPrompt, scenarioId)
  }

  const allMessages: LLMMessage[] = [
    { role: 'system', content: systemPrompt },
    ...messages,
  ]

  try {
    const response = await fetch(API_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${API_KEY}`,
      },
      body: JSON.stringify({
        model: MODEL,
        messages: allMessages,
        temperature: 0.85,
        max_tokens: 512,
        do_sample: true,
      }),
    })

    if (!response.ok) {
      const errorText = await response.text()
      console.error('GLM API error:', response.status, errorText)
      return mockCall(messages, systemPrompt, scenarioId)
    }

    const data = await response.json()
    const content = data.choices?.[0]?.message?.content || ''

    return parseLLMResponse(content)
  } catch (err) {
    console.error('GLM API request failed:', err)
    return mockCall(messages, systemPrompt, scenarioId)
  }
}

function parseLLMResponse(content: string): LLMResponse {
  const cleaned = content.trim()

  const codeBlockMatch = cleaned.match(/```(?:json)?\s*([\s\S]*?)\s*```/)
  if (codeBlockMatch) {
    try {
      const parsed = JSON.parse(codeBlockMatch[1].trim()) as LLMResponse
      if (typeof parsed.reply === 'string' && typeof parsed.is_resolved === 'boolean') {
        return parsed
      }
    } catch {
      // 解析失败，继续尝试其他方式
    }
  }

  const jsonMatch = cleaned.match(/\{[\s\S]*?"reply"[\s\S]*?"is_resolved"[\s\S]*?\}/)
  if (jsonMatch) {
    try {
      const parsed = JSON.parse(jsonMatch[0]) as LLMResponse
      if (typeof parsed.reply === 'string' && typeof parsed.is_resolved === 'boolean') {
        return parsed
      }
    } catch {
      // 解析失败，继续尝试
    }
  }

  const looseJsonMatch = cleaned.match(/\{[\s\S]*\}/)
  if (looseJsonMatch) {
    try {
      const parsed = JSON.parse(looseJsonMatch[0]) as LLMResponse
      if (typeof parsed.reply === 'string' && typeof parsed.is_resolved === 'boolean') {
        return parsed
      }
    } catch {
      // 解析失败
    }
  }

  const reply = cleaned
    .replace(/```json\s*/gi, '')
    .replace(/```\s*/gi, '')
    .trim()

  return { reply: reply || '……', emotion: 'calm', is_resolved: false }
}

function mockCall(
  _messages: LLMMessage[],
  _systemPrompt: string,
  scenarioId: string
): Promise<LLMResponse> {
  if (mockIndex[scenarioId] === undefined) {
    mockIndex[scenarioId] = 0
  }

  const responses = MOCK_RESPONSES[scenarioId] || []
  const idx = Math.min(mockIndex[scenarioId], responses.length - 1)
  mockIndex[scenarioId] = idx + 1

  return new Promise((resolve) => {
    setTimeout(() => {
      resolve(responses[idx] || { reply: '……', emotion: 'calm', is_resolved: false })
    }, 800 + Math.random() * 700)
  })
}
