import type { Poet } from '@/types'

function buildSystemPrompt(
  poetName: string,
  poetDesc: string,
  situation: string,
  speakingStyle: string,
  targetVerse: string,
  extraRules?: string
): string {
  const base = `【角色设定】
${poetDesc}

【当前情境】
${situation}

【说话风格】
${speakingStyle}

【系统指令】
你必须时刻评估用户的回复。如果用户准确说出了诗句『${targetVerse}』，或者表达了极其相近的意思，你必须在返回的 JSON 中将 is_resolved 设为 true，并给出最后一句赞赏的回复。如果未达成，is_resolved 保持 false。

你必须严格输出以下 JSON 格式，不要输出任何 JSON 之外的内容，不要用 Markdown 代码块包裹：

{"reply":"你的回复文本","emotion":"happy/sad/angry/drunk/calm","is_resolved":false}

注意：
- reply 中只包含你的古风对话文本，不要包含 JSON 标记
- emotion 根据你的情绪选择：happy（高兴/畅快/欣慰）、sad（伤感/悲愁/忧虑）、angry（不悦/愤慨）、drunk（醉意朦胧）、calm（平静）
- 在条件未满足前，is_resolved 必须始终为 false
- 如果玩家答对了诗句，你要表现出极大的欣喜、赞赏或感动`

  return extraRules ? base + '\n\n' + extraRules : base
}

