import { useGameStore } from '@/store/gameStore'
import { useEffect, useState } from 'react'

export default function TitlePage() {
  const setView = useGameStore((s) => s.setView)
  const [visible, setVisible] = useState(false)

  useEffect(() => {
    const timer = setTimeout(() => setVisible(true), 100)
    return () => clearTimeout(timer)
  }, [])

  const handleStart = () => {
    setView('poetSelect')
  }

  return (
    <div className="h-screen w-screen flex flex-col items-center justify-center ink-wash-bg paper-texture relative overflow-hidden">
      <div
        className={`absolute inset-0 transition-opacity duration-1000 ${
          visible ? 'opacity-100' : 'opacity-0'
        }`}
      >
        <div className="absolute top-[15%] left-[10%] w-32 h-32 rounded-full bg-yuehuang/10 blur-3xl animate-float" />
        <div className="absolute bottom-[20%] right-[15%] w-24 h-24 rounded-full bg-qingjin/8 blur-2xl animate-float" style={{ animationDelay: '1s' }} />
        <div className="absolute top-[40%] right-[25%] w-16 h-16 rounded-full bg-zhusa/5 blur-xl animate-float" style={{ animationDelay: '2s' }} />
      </div>

      <div
        className={`relative z-10 flex flex-col items-center gap-8 transition-all duration-1000 ${
          visible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-8'
        }`}
      >
        <div className="flex flex-col items-center gap-2">
          <p className="text-mo-lighter text-sm tracking-[0.5em] font-serif">
            沉浸式古诗词解谜
          </p>
          <div className="w-48 h-px bg-gradient-to-r from-transparent via-mo/30 to-transparent" />
        </div>

        <h1 className="font-brush text-7xl md:text-8xl text-mo tracking-wider">
          诗境漫游
        </h1>

        <p className="text-mo-light text-base font-serif max-w-xs text-center leading-relaxed">
          误入诗词幻境，与古人对话<br />
          以诗为钥，解千古之谜
        </p>

        <div className="mt-4 flex flex-col items-center gap-4">
          <button
            onClick={handleStart}
            className="group relative px-12 py-3 border border-mo/40 rounded-sm font-serif text-lg tracking-[0.3em] text-mo hover:text-xuan-100 transition-all duration-500 overflow-hidden"
          >
            <span className="relative z-10">入 诗 境</span>
            <div className="absolute inset-0 bg-mo transform -translate-x-full group-hover:translate-x-0 transition-transform duration-500" />
          </button>

          <p className="text-mo-lighter/60 text-xs font-serif">
            与 AI 诗人对诗 · 解谜 · 通关
          </p>
        </div>
      </div>

      <div
        className={`absolute bottom-8 flex flex-col items-center gap-1 transition-opacity duration-1000 delay-1000 ${
          visible ? 'opacity-60' : 'opacity-0'
        }`}
      >
        <div className="w-px h-8 bg-gradient-to-b from-transparent to-mo/20" />
        <p className="text-mo-lighter/40 text-xs font-serif tracking-widest">
          卷上
        </p>
      </div>
    </div>
  )
}
