import { useGameStore } from '@/store/gameStore'
import { Target, Scroll } from 'lucide-react'

export default function ObjectiveHint() {
  const selectedPoem = useGameStore((s) => s.selectedPoem)
  const isResolved = useGameStore((s) => s.isResolved)

  if (!selectedPoem) return null

  return (
    <div className="absolute top-4 right-4 z-20 animate-fade-in">
      <div className="bg-xuan-100/90 backdrop-blur-sm border border-zhuqing/30 rounded-sm px-4 py-3 shadow-sm max-w-[220px]">
        <div className="flex items-center gap-2 mb-2">
          <Target size={14} className="text-zhuqing" />
          <span className="text-xs font-serif text-zhuqing-dark tracking-wider">
            当前目标
          </span>
        </div>
        <p className="text-sm font-serif text-mo leading-relaxed">
          {isResolved ? '✦ 已达成' : selectedPoem.clearCondition}
        </p>
        <div className="mt-2 flex items-center gap-2">
          <Scroll size={12} className="text-mo-lighter" />
          <span className="text-xs font-serif text-mo-lighter">
            {selectedPoem.title}
          </span>
        </div>
      </div>
    </div>
  )
}
