import { useGameStore } from '@/store/gameStore'
import TitlePage from '@/pages/TitlePage'
import PoetSelectPage from '@/pages/PoetSelectPage'
import PoemSelectPage from '@/pages/PoemSelectPage'
import ContextReadPage from '@/pages/ContextReadPage'
import GamePage from '@/pages/GamePage'

export default function App() {
  const currentView = useGameStore((s) => s.currentView)

  switch (currentView) {
    case 'title':
      return <TitlePage />
    case 'poetSelect':
      return <PoetSelectPage />
    case 'poemSelect':
      return <PoemSelectPage />
    case 'contextRead':
      return <ContextReadPage />
    case 'chat':
      return <GamePage />
    default:
      return <TitlePage />
  }
}
