import { useGameStore } from '@/store/gameStore'
import { ArrowLeft, ScrollText } from 'lucide-react'

export default function PoemSelectPage() {
  const selectedPoet = useGameStore((s) => s.selectedPoet)
  const selectPoem = useGameStore((s) => s.selectPoem)
  const setView = useGameStore((s) => s.setView)

  if (!selectedPoet) {
    setView('poetSelect')
    return null
  }

  return (
    <div className="h-screen w-screen flex flex-col items-center ink-wash-bg paper-texture overflow-y-auto">
      <div className="w-full max-w-[960px] px-6 py-8">
        <div className="flex items-center gap-4 mb-8">
          <button
            onClick={() => setView('poetSelect')}
            className="w-8 h-8 flex items-center justify-center rounded-sm border border-mo/20 text-mo hover:bg-mo hover:text-xuan-100 transition-all"
          >
            <ArrowLeft size={16} />
          </button>
          <div className="flex items-center gap-3">
            <img
              src={selectedPoet.avatarUrl}
              alt={selectedPoet.name}
              className="w-10 h-10 rounded-full border border-mo/10"
            />
            <div>
              <h1 className="font-brush text-3xl text-mo tracking-wider">
                {selectedPoet.name}
              </h1>
              <p className="text-xs text-mo-lighter font-serif">
                {selectedPoet.shortDesc}
              </p>
            </div>
          </div>
        </div>

        <div className="flex flex-col gap-4">
          {selectedPoet.poems.map((poem) => (
            <button
              key={poem.id}
              onClick={() => selectPoem(poem)}
              className="group flex items-start gap-4 p-5 bg-xuan-100/60 border border-mo/10 rounded-sm hover:border-qingjin/40 hover:bg-xuan-100/90 transition-all duration-500 text-left"
            >
              <div className="w-10 h-10 rounded-sm bg-qingjin/10 flex items-center justify-center flex-shrink-0 mt-0.5">
                <ScrollText size={18} className="text-qingjin" />
              </div>

              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2 mb-1">
                  <h2 className="font-brush text-lg text-mo group-hover:text-qingjin transition-colors">
                    {poem.title}
                  </h2>
                  <span className="text-[10px] text-mo-lighter/60 font-serif border border-mo/10 px-1.5 py-0.5 rounded-sm">
                    {poem.dynasty}
                  </span>
                </div>
                <p className="text-xs text-mo-lighter font-serif leading-relaxed line-clamp-2">
                  {poem.clearCondition}
                </p>
              </div>

              <div className="text-mo-lighter/30 group-hover:text-qingjin/60 transition-colors">
                <ArrowLeft size={16} className="rotate-180" />
              </div>
            </button>
          ))}
        </div>
      </div>
    </div>
  )
}
