import { useEffect, useState } from 'react'
import { useGameStore } from '@/store/gameStore'
import { Sparkles, ArrowLeft } from 'lucide-react'

export default function LevelTransition() {
  const isTransitioning = useGameStore((s) => s.isTransitioning)
  const selectedPoem = useGameStore((s) => s.selectedPoem)
  const returnToPoemSelect = useGameStore((s) => s.returnToPoemSelect)
  const [particles, setParticles] = useState<number[]>([])
  const [phase, setPhase] = useState<'celebration' | 'done'>('celebration')

  useEffect(() => {
    if (!isTransitioning) {
      setPhase('celebration')
      return
    }

    const newParticles = Array.from({ length: 16 }, (_, i) => i)
    setParticles(newParticles)

    const timer = setTimeout(() => {
      setPhase('done')
    }, 2500)

    return () => clearTimeout(timer)
  }, [isTransitioning])

  if (!isTransitioning) return null

  const poemTitle = selectedPoem?.title || ''

  return (
    <div className="absolute inset-0 z-50 flex items-center justify-center bg-xuan-100/92 backdrop-blur-sm animate-fade-in">
      {phase === 'celebration' && (
        <div className="flex flex-col items-center gap-5 animate-slide-up">
          <div className="relative">
            <Sparkles size={48} className="text-yuehuang animate-float" />
            {particles.map((i) => (
              <div
                key={i}
                className="absolute w-2 h-2 rounded-full bg-yuehuang/80 animate-particle-rise"
                style={{
                  left: `${Math.random() * 100 - 50}px`,
                  top: `${Math.random() * 50 - 25}px`,
                  animationDelay: `${i * 0.12}s`,
                }}
              />
            ))}
          </div>
          <h2 className="font-brush text-4xl text-mo tracking-wider">
            诗境堪破
          </h2>
          <p className="text-mo-light font-serif text-center max-w-xs leading-relaxed">
            {poemTitle}<br />
            诗意相通，心心相印
          </p>
        </div>
      )}

      {phase === 'done' && (
        <div className="flex flex-col items-center gap-6 animate-fade-in">
          <div className="w-16 h-16 rounded-full bg-yuehuang/20 flex items-center justify-center">
            <Sparkles size={32} className="text-yuehuang" />
          </div>
          <h3 className="font-brush text-2xl text-mo tracking-wider">
            通关
          </h3>
          <p className="text-mo-lighter font-serif text-sm text-center max-w-xs">
            你已领悟此诗真意<br />
            可返回选择其他诗篇继续探索
          </p>
          <button
            onClick={returnToPoemSelect}
            className="mt-2 flex items-center gap-2 px-6 py-2.5 border border-mo/30 rounded-sm font-serif text-sm text-mo hover:bg-mo hover:text-xuan-100 transition-all duration-300"
          >
            <ArrowLeft size={14} />
            返回剧本选择
          </button>
        </div>
      )}
    </div>
  )
}
