import type { ChatMessage as ChatMessageType } from '@/types'
import { Volume2, VolumeX } from 'lucide-react'
import { useGameStore } from '@/store/gameStore'

const emotionLabels: Record<string, string> = {
  happy: '欣喜',
  sad: '悲愁',
  angry: '愤慨',
  drunk: '醉意',
  calm: '平静',
}

interface Props {
  message: ChatMessageType
}

export default function ChatBubble({ message }: Props) {
  const isPlayer = message.role === 'player'
  const isSystem = message.role === 'system'
  const ttsEnabled = useGameStore((state) => state.ttsEnabled)
  const isPlaying = useGameStore((state) => state.isPlaying)
  const playingMessageId = useGameStore((state) => state.playingMessageId)
  const speak = useGameStore((state) => state.speak)
  const stopSpeaking = useGameStore((state) => state.stopSpeaking)

  const isThisPlaying = isPlaying && playingMessageId === message.id

  if (isSystem) {
    return (
      <div className="flex justify-center animate-fade-in">
        <div className="max-w-[85%] bg-yuehuang/10 border border-yuehuang/30 rounded-sm px-4 py-2.5">
          <p className="text-xs font-serif text-mo-light leading-relaxed">
            {message.content}
          </p>
        </div>
      </div>
    )
  }

  return (
    <div
      className={`flex ${isPlayer ? 'justify-end' : 'justify-start'} animate-slide-up`}
    >
      {!isPlayer && ttsEnabled && (
        <div className="flex items-end gap-1.5 mr-2 order-1 mb-5">
          <button
            onClick={() =>
              isThisPlaying
                ? stopSpeaking()
                : speak(message.content, message.id)
            }
            className="p-1.5 rounded-full bg-yuehuang/10 border border-yuehuang/20 text-yuehuang hover:bg-yuehuang/20 transition-colors"
            title={isThisPlaying ? '停止朗读' : '朗读消息'}
          >
            {isThisPlaying ? (
              <VolumeX className="w-3.5 h-3.5" />
            ) : (
              <Volume2 className="w-3.5 h-3.5" />
            )}
          </button>
          {isThisPlaying && (
            <div className="tts-wave-container">
              <span className="tts-wave" />
              <span className="tts-wave" />
              <span className="tts-wave" />
            </div>
          )}
        </div>
      )}

      <div className={`max-w-[75%] ${isPlayer ? 'order-1' : 'order-2'}`}>
        {!isPlayer && message.emotion && (
          <div className="flex items-center gap-1.5 mb-1 ml-1">
            <span className="text-[10px] text-mo-lighter font-serif">
              {emotionLabels[message.emotion] || message.emotion}
            </span>
          </div>
        )}

        <div
          className={`px-4 py-2.5 rounded-sm font-serif text-sm leading-relaxed ${
            isPlayer
              ? 'chat-bubble-player text-mo'
              : 'chat-bubble-npc text-mo'
          }`}
        >
          {message.content}
        </div>

        <div
          className={`text-[10px] text-mo-lighter/50 font-serif mt-1 ${
            isPlayer ? 'text-right mr-1' : 'ml-1'
          }`}
        >
          {new Date(message.timestamp).toLocaleTimeString('zh-CN', {
            hour: '2-digit',
            minute: '2-digit',
          })}
        </div>
      </div>
    </div>
  )
}
