import { useState, useCallback } from 'react'
import { useGameStore } from '@/store/gameStore'
import { Send, Lightbulb, Volume2, VolumeX } from 'lucide-react'

export default function InputArea() {
  const [input, setInput] = useState('')
  const sendMessage = useGameStore((s) => s.sendMessage)
  const showHint = useGameStore((s) => s.showHint)
  const isLoading = useGameStore((s) => s.isLoading)
  const isResolved = useGameStore((s) => s.isResolved)
  const isTransitioning = useGameStore((s) => s.isTransitioning)
  const ttsEnabled = useGameStore((s) => s.ttsEnabled)
  const toggleTTS = useGameStore((s) => s.toggleTTS)

  const disabled = isLoading || isResolved || isTransitioning

  const handleSend = useCallback(() => {
    const trimmed = input.trim()
    if (!trimmed || disabled) return
    sendMessage(trimmed)
    setInput('')
  }, [input, disabled, sendMessage])

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault()
        handleSend()
      }
    },
    [handleSend]
  )

  const handleHint = useCallback(() => {
    showHint()
  }, [showHint])

  return (
    <div className="border-t border-mo/10 bg-xuan-100/95 backdrop-blur-sm px-4 py-3">
      <div className="flex items-center gap-2">
        <button
          onClick={toggleTTS}
          title={ttsEnabled ? '语音朗读' : '已关闭语音'}
          className={`w-9 h-9 flex items-center justify-center rounded-sm border transition-all duration-300 ${
            ttsEnabled
              ? 'border-qingjin/40 text-qingjin hover:bg-qingjin/20'
              : 'border-mo/20 text-mo-lighter hover:bg-mo/10'
          }`}
        >
          {ttsEnabled ? <Volume2 size={15} /> : <VolumeX size={15} />}
        </button>

        <button
          onClick={handleHint}
          disabled={disabled}
          title="锦囊"
          className="w-9 h-9 flex items-center justify-center rounded-sm border border-yuehuang/40 text-yuehuang-dark hover:bg-yuehuang/20 transition-all duration-300 disabled:opacity-30 disabled:cursor-not-allowed"
        >
          <Lightbulb size={15} />
        </button>

        <input
          type="text"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder={
            disabled
              ? '请稍候……'
              : '输入你的话语……'
          }
          disabled={disabled}
          className="flex-1 bg-xuan-200/50 border border-mo/10 rounded-sm px-4 py-2.5 font-serif text-sm text-mo placeholder:text-mo-lighter/50 focus:outline-none focus:border-qingjin/40 transition-colors disabled:opacity-50"
        />
        <button
          onClick={handleSend}
          disabled={disabled || !input.trim()}
          className="w-10 h-10 flex items-center justify-center rounded-sm border border-mo/20 text-mo hover:bg-mo hover:text-xuan-100 transition-all duration-300 disabled:opacity-30 disabled:cursor-not-allowed disabled:hover:bg-transparent disabled:hover:text-mo"
        >
          <Send size={16} />
        </button>
      </div>
    </div>
  )
}
