import { useEffect, useRef } from 'react'
import { useGameStore } from '@/store/gameStore'
import ChatBubble from './ChatBubble'
import { Loader2 } from 'lucide-react'

export default function ChatArea() {
  const messages = useGameStore((s) => s.messages)
  const isLoading = useGameStore((s) => s.isLoading)
  const bottomRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [messages, isLoading])

  return (
    <div className="flex-1 overflow-y-auto px-4 py-3 paper-texture">
      <div className="flex flex-col gap-3">
        {messages.map((msg) => (
          <ChatBubble key={msg.id} message={msg} />
        ))}

        {isLoading && (
          <div className="flex justify-start animate-fade-in">
            <div className="chat-bubble-npc px-4 py-3 rounded-sm flex items-center gap-2">
              <Loader2 size={14} className="animate-spin text-qingjin" />
              <span className="text-xs text-mo-lighter font-serif">
                思索中……
              </span>
            </div>
          </div>
        )}

        <div ref={bottomRef} />
      </div>
    </div>
  )
}
